    size_t i;
    size_t j;
    adcs_vec3_t residual = {0.0, 0.0, 0.0};
    adcs_vec3_t axis;
    double norm;

    if ((axes == NULL) || (wheel_torque_nm == NULL) || (spacecraft_residual_nm == NULL)) {
        return ADCS_E_NULL;
    }

    if (!isfinite(amplitude_nm)) {
        for (j = 0; j < 4U; j++) {
            wheel_torque_nm[j] = 0.0;
        }
        *spacecraft_residual_nm = (adcs_vec3_t){0.0, 0.0, 0.0};
        return ADCS_E_RANGE;
    }

    for (i = 0; i < 4U; i++) {
        if (!adcs_is_finite_vec3(&axes[i])) {
            for (j = 0; j < 4U; j++) {
                wheel_torque_nm[j] = 0.0;
            }
            *spacecraft_residual_nm = (adcs_vec3_t){0.0, 0.0, 0.0};
            return ADCS_E_RANGE;
        }
        norm = adcs_vec3_norm(&axes[i]);
        if ((!isfinite(norm)) || (fabs(norm - 1.0) > ADCS_EPS_COLLINEAR)) {
            for (j = 0; j < 4U; j++) {
                wheel_torque_nm[j] = 0.0;
            }
            *spacecraft_residual_nm = (adcs_vec3_t){0.0, 0.0, 0.0};
            return ADCS_E_RANGE;
        }
    }

    for (i = 0; i < 4U; i++) {
        wheel_torque_nm[i] = amplitude_nm;
        axis = adcs_vec3_scale(&axes[i], wheel_torque_nm[i]);
        residual = adcs_vec3_add(&residual, &axis);
    }

    *spacecraft_residual_nm = adcs_vec3_scale(&residual, -1.0);
    return ADCS_OK;
}

